CREATE MASKING POLICY IF NOT EXISTS SEC.MP_RESTRICTED_TEXT AS (v STRING) RETURNS STRING -> v
  COMMENT = 'Column grants (SEC.MAP_ROLE_GRANT keyed by ACCESS_GROUP tag) and ABAC deny rules (ABAC_POLICY tag)';

ALTER MASKING POLICY SEC.MP_RESTRICTED_TEXT SET BODY ->
    CASE
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',REGULATORY_SENSITIVE_DATA,') AND NOT (IS_ROLE_IN_SESSION('COMPLIANCE_OFFICERS') OR IS_ROLE_IN_SESSION('NERC_AUDITORS') OR IS_ROLE_IN_SESSION('REPORT_ADMINS')) THEN '*** Restricted ***'
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',SENSITIVE_DATA_POLICY,') AND COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') = 'restricted' THEN '*** Restricted ***'
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',SENSITIVE_FINANCIAL_DATA,') AND (COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') <> 'restricted' AND COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') <> 'confidential') THEN '*** Restricted ***'
    WHEN SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ACCESS_GROUP') IS NULL THEN v
    WHEN EXISTS (SELECT 1 FROM SEC.MAP_ROLE_GRANT g WHERE g.ACCESS_GROUP = SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ACCESS_GROUP') AND g.GRANT_TYPE = 'DENY' AND IS_ROLE_IN_SESSION(g.ROLE_NAME)) THEN '*** Restricted ***'
    WHEN EXISTS (SELECT 1 FROM SEC.MAP_ROLE_GRANT g WHERE g.ACCESS_GROUP = SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ACCESS_GROUP') AND g.GRANT_TYPE = 'ALLOW' AND IS_ROLE_IN_SESSION(g.ROLE_NAME)) THEN v
    ELSE '*** Restricted ***'
    END;

ALTER MASKING POLICY SEC.MP_RESTRICTED_TEXT SET COMMENT = 'Column grants (SEC.MAP_ROLE_GRANT keyed by ACCESS_GROUP tag) and ABAC deny rules (ABAC_POLICY tag)';
